/** Physical pg_dump/pg_restore, production Spring/JPA transactions and independent private files.
 * No production accounts, providers, native application schema, or SMTP credentials. */
class PrivacyPostBackupHoldsIT {
    private static RealPostgres database;@TempDir Path temporary;private ServletWebServerApplicationContext app;private JdbcTemplate sql;private Path operations,storage;private String[] args;private Actor administrator;private String hash;
    private static final String PASSWORD="Synthetic post-backup recovery password 2026";
    private static final byte[] BYTES={31,41,59,26};
    @BeforeAll static void open(){database=new RealPostgres();}
    @AfterAll static void finish(){if(database!=null)database.close();}
    @AfterEach void close(){if(app!=null){app.close();app=null;}}
    @BeforeEach void setup()throws Exception {
        database.resetSchema();operations=temporary.resolve("ops");storage=temporary.resolve("files");var values=new ArrayList<>(List.of(AuthTestSettings.arguments(database.apiConnectionUrl())));values.addAll(List.of("--PRIVACY_OPERATIONS_ROOT="+operations,"--STORAGE_PATH="+storage,"--DEV_MAIL_PATH="+temporary.resolve("mail"),"--PRIVACY_ERASURE_JOURNAL_PATH="+temporary.resolve("suppression"),"--PRIVACY_EVIDENCE_KEY_ID=e1","--PRIVACY_EVIDENCE_KEYS={\"e1\":\""+"cd".repeat(32)+"\"}","--PRIVACY_JOURNAL_KEY_ID=j1","--PRIVACY_JOURNAL_KEYS={\"j1\":\""+"B".repeat(43)+"\"}"));args=values.toArray(String[]::new);
        var env=new MockEnvironment();for(String arg:args){int at=arg.indexOf('=');env.withProperty(arg.substring(2,at),arg.substring(at+1));}var json=new ObjectMapper();var crypto=new CryptoService();var auth=new AuthSettings(env);var files=new StorageSettings(env);new PrivacyBackupCatalog(new PrivacyOperationsSettings(env,files),new PrivacySettings(env),new PrivacySigningKeys(env,auth,crypto,json),json,Clock.systemUTC()).initialize();
        start();hash=app.getBean(CryptoService.class).hashPassword(PASSWORD);UUID admin=user("Synthetic administrator");sql.update("UPDATE users SET role='admin' WHERE id=?",admin);UUID session=UUID.randomUUID(),family=UUID.randomUUID();sql.update("INSERT INTO sessions(id,user_id,access_hash,refresh_hash,csrf_hash,family_id,access_expires_at,refresh_expires_at) VALUES(?,?,?,?,?,?,now()+interval '1 day',now()+interval '7 days')",session,admin,UUID.randomUUID().toString(),UUID.randomUUID().toString(),"synthetic-csrf",family);administrator=new Actor(admin,"admin","active",session,family,"synthetic-csrf",true,Set.of("ROLE_ADMIN"));
    }
    private void start(){app=(ServletWebServerApplicationContext)new SpringApplicationBuilder(UniCaronaApplication.class).run(args);sql=app.getBean(JdbcTemplate.class);}
    private UUID user(String name){return sql.queryForObject("INSERT INTO users(email,password_hash,name,birth_date,email_verified_at) VALUES(?,?,?,'2000-01-01',now()) RETURNING id",UUID.class,UUID.randomUUID()+"@example.test",hash==null?"Synthetic no login fixture":hash,name);}
    private Path archive(String name)throws Exception {Path result=temporary.resolve(name+".dump");database.dumpDatabaseArchive(result);return result;}
    private void restore(Path archive)throws Exception {app.close();app=null;database.resetSchema();database.restoreDatabaseArchive(archive);start();}
    private UUID file(UUID owner)throws Exception {UUID id=UUID.randomUUID();String sha=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(BYTES));sql.update("INSERT INTO stored_files(id,owner_id,purpose,storage_key,content_type,byte_size,sha256) VALUES(?,?,'identity',?,'image/png',?,?)",id,owner,id.toString(),BYTES.length,sha);app.getBean(PrivateFileStorage.class).put(id.toString(),BYTES);return id;}
    private PrivacyHoldDto.Item hold(UUID owner,String category,UUID resource){return app.getBean(AdminPrivacyHoldService.class).create(administrator,new PrivacyHoldDto.Create(PASSWORD,owner,category,resource,"regular_exercise_of_rights","Synthetic precisely scoped evidence for this test case","Synthetic recovery case",Instant.now().plusSeconds(3600),Instant.now().plusSeconds(86400)),UUID.randomUUID().toString());}
    private PrivacyHoldDto.Item review(PrivacyHoldDto.Item hold,boolean release){return app.getBean(AdminPrivacyHoldService.class).review(administrator,hold.id(),new PrivacyHoldDto.Review(PASSWORD,hold.revision(),release?"release":"review","Synthetic reviewed need for this specific evidence","Synthetic reviewed case",release?null:Instant.now().plusSeconds(7200),release?null:Instant.now().plusSeconds(172800)),UUID.randomUUID().toString());}
    private void erase(UUID owner)throws Exception {Instant at=Instant.now();var journal=app.getBean(PrivacyErasureJournal.class);journal.ensure(owner,UUID.randomUUID(),at,at.plus(Duration.ofDays(37)));app.getBean(PrivacyErasureMaintenance.class).replay(journal.entries().stream().filter(e->e.owner().equals(owner)).findFirst().orElseThrow());}
    private AdminPrivacyHoldTransactions.HeldData data(UUID hold){return app.getBean(AdminPrivacyHoldService.class).heldData(administrator,hold,new PrivacyDto.Reauthenticate(PASSWORD));}
    private void ready(){assertTrue(app.getBean(PrivacyReadiness.class).ready());assertFalse(app.getBean(PrivacyHoldControlTransactions.class).marker().pending());}
    private void nextKeys(boolean keepPrevious){var values=new ArrayList<String>();for(String arg:args)if(!arg.startsWith("--PRIVACY_EVIDENCE_KEY")&&!arg.startsWith("--PRIVACY_JOURNAL_KEY"))values.add(arg);values.addAll(List.of("--PRIVACY_EVIDENCE_KEY_ID=e2","--PRIVACY_EVIDENCE_KEYS={"+(keepPrevious?"\"e1\":\""+"cd".repeat(32)+"\",":"")+"\"e2\":\""+"ef".repeat(32)+"\"}","--PRIVACY_JOURNAL_KEY_ID=j2","--PRIVACY_JOURNAL_KEYS={"+(keepPrevious?"\"j1\":\""+"B".repeat(43)+"\",":"")+"\"j2\":\""+"C".repeat(43)+"\"}"));args=values.toArray(String[]::new);}
    @Test void decisionsAndFileCreatedAfterTheArchiveRecoverBeforeAccountSuppressionWithoutRepublishingTheIdentity()throws Exception {
        UUID owner=user("Synthetic original name"),peer=user("Synthetic preserved peer");Path before=archive("before-decisions");var profile=hold(owner,"profile",owner);UUID document=file(owner);var fileHold=hold(owner,"files",document);profile=review(profile,false);String deadline=profile.expiresAt();erase(owner);long checkpoint=app.getBean(PrivacyHoldControlTransactions.class).marker().sequence();Files.delete(storage.resolve(document.toString()));
        restore(before);ready();assertTrue(app.getBean(PrivacyHoldControlTransactions.class).marker().sequence()>=checkpoint);assertEquals("Conta excluída",sql.queryForObject("SELECT name FROM users WHERE id=?",String.class,owner));assertEquals("Synthetic preserved peer",sql.queryForObject("SELECT name FROM users WHERE id=?",String.class,peer));
        var recovered=app.getBean(AdminPrivacyHoldService.class).detail(administrator,profile.id(),new PrivacyDto.Reauthenticate(PASSWORD));assertEquals(2,recovered.hold().revision());assertEquals(deadline,recovered.hold().expiresAt());assertEquals(2,recovered.history().size());assertTrue(new String(data(profile.id()).data(),java.nio.charset.StandardCharsets.UTF_8).contains("Synthetic original name"));assertArrayEquals(BYTES,data(fileHold.id()).data());assertNotNull(sql.queryForObject("SELECT deleted_at FROM stored_files WHERE id=?",Timestamp.class,document));assertNull(sql.queryForObject("SELECT photo_file_id FROM users WHERE id=?",UUID.class,owner));
    }
    @Test void aReleaseAfterTheArchiveWinsOverItsOlderActiveHoldsAndDoesNotRecoverReleasedBytes()throws Exception {
        UUID owner=user("Synthetic release owner"),document=file(owner);var profile=hold(owner,"profile",owner);var fileHold=hold(owner,"files",document);erase(owner);Path before=archive("before-release");profile=review(profile,true);fileHold=review(fileHold,true);app.getBean(PrivacyRetentionTransactions.class).prune(100);assertTrue(app.getBean(PrivacyFileErasure.class).erase(document));assertFalse(Files.exists(storage.resolve(document.toString())));Files.write(storage.resolve(document.toString()),BYTES);
        restore(before);ready();for(var h:List.of(profile,fileHold)){var row=sql.queryForMap("SELECT released_at,revision FROM privacy_legal_holds WHERE id=?",h.id());assertNotNull(row.get("released_at"));assertEquals(2,((Number)row.get("revision")).intValue());}assertEquals(0,sql.queryForObject("SELECT count(*) FROM privacy_retained_records WHERE user_id=? AND hold_only",Integer.class,owner));assertFalse(Files.exists(storage.resolve(document.toString())));UUID releasedFileHold=fileHold.id();assertThrows(com.unicarona.shared.ApiException.class,()->data(releasedFileHold));
    }
    @Test void corruptIndependentBytesBlockReadinessAndRollbackTheTypedDatabaseReplay()throws Exception {
        UUID owner=user("Synthetic corrupt-copy owner");Path before=archive("before-corrupt-file");UUID document=file(owner);hold(owner,"files",document);Path copy;try(var paths=Files.list(operations.resolve("hold-control-files"))){copy=paths.findFirst().orElseThrow();}Files.writeString(copy,"{}");app.close();app=null;database.resetSchema();database.restoreDatabaseArchive(before);assertThrows(Exception.class,this::start);assertNull(app);var restored=new JdbcTemplate(database.dataSource());assertEquals(0,restored.queryForObject("SELECT count(*) FROM privacy_legal_holds",Integer.class));assertEquals(0L,restored.queryForObject("SELECT sequence FROM privacy_hold_control_state",Long.class));assertTrue(Files.exists(copy));
    }
    @Test void anOwnerMissingFromTheArchiveNeedsAssistedRecoveryAndIsNeverFabricated()throws Exception {
        Path before=archive("before-owner");UUID owner=user("Synthetic post-backup owner");hold(owner,"profile",owner);app.close();app=null;database.resetSchema();database.restoreDatabaseArchive(before);assertThrows(Exception.class,this::start);assertNull(app);var restored=new JdbcTemplate(database.dataSource());assertFalse(Boolean.TRUE.equals(restored.queryForObject("SELECT EXISTS(SELECT 1 FROM users WHERE id=?)",Boolean.class,owner)));assertEquals(0,restored.queryForObject("SELECT count(*) FROM privacy_legal_holds",Integer.class));try(var copies=Files.list(operations.resolve("hold-control"))){assertTrue(copies.findAny().isPresent());}
    }
    @Test void anUnrecognizedSnapshotFieldCannotBecomeAnInstructionDuringRestore()throws Exception {
        UUID owner=user("Synthetic closed schema owner");Path before=archive("before-invalid-control");hold(owner,"profile",owner);app.getBean(TransactionTemplate.class).executeWithoutResult(ignored->app.getBean(PrivacyHoldControlTransactions.class).stage(()->{try{var state=(com.fasterxml.jackson.databind.node.ObjectNode)app.getBean(PrivacyRetentionSnapshot.class).capture();return state.put("executeSql","DROP TABLE users");}catch(Exception invalid){throw new IllegalStateException("Synthetic capture failed");}}));assertThrows(java.io.IOException.class,()->app.getBean(PrivacyHoldRecovery.class).cleanup(100));try(var records=Files.list(operations.resolve("hold-control"))){assertEquals(2,records.count(),"An invalid current schema must not authorize deleting the previous control");}app.close();app=null;database.resetSchema();database.restoreDatabaseArchive(before);assertThrows(Exception.class,this::start);assertNull(app);assertTrue(new JdbcTemplate(database.dataSource()).queryForObject("SELECT EXISTS(SELECT 1 FROM users WHERE id=?)",Boolean.class,owner));
    }
    @Test void anOriginalDeadlineThatElapsedAfterCaptureDoesNotGetAnotherLifetimeOnRestore()throws Exception {
        UUID owner=user("Synthetic expiring evidence owner");Path before=archive("before-expiring-holds");UUID document=file(owner);Instant deadline=Instant.now().plusSeconds(7).truncatedTo(java.time.temporal.ChronoUnit.MICROS);
        var service=app.getBean(AdminPrivacyHoldService.class);var items=new ArrayList<PrivacyHoldDto.Item>();for(String category:List.of("profile","files"))items.add(service.create(administrator,new PrivacyHoldDto.Create(PASSWORD,owner,category,category.equals("profile")?owner:document,"regular_exercise_of_rights","Synthetic evidence with a deliberately short original deadline","Synthetic expiry test",Instant.now().plusSeconds(1),deadline),UUID.randomUUID().toString()));
        assertTrue(app.getBean(PrivacyHoldControlJournal.class).current().orElseThrow().state().path("files").size()>0);Files.delete(storage.resolve(document.toString()));long remaining=Duration.between(Instant.now(),deadline.plusMillis(100)).toMillis();assertTrue(remaining<8000);if(remaining>0)Thread.sleep(remaining);
        restore(before);ready();assertFalse(Files.exists(storage.resolve(document.toString())));assertEquals(0,sql.queryForObject("SELECT count(*) FROM privacy_retained_records WHERE user_id=?",Integer.class,owner));assertEquals(0,app.getBean(PrivacyHoldControlJournal.class).current().orElseThrow().state().path("files").size());for(var item:items){assertEquals(Timestamp.from(deadline).toInstant().truncatedTo(java.time.temporal.ChronoUnit.MICROS),sql.queryForObject("SELECT expires_at FROM privacy_legal_holds WHERE id=?",Timestamp.class,item.id()).toInstant());assertThrows(com.unicarona.shared.ApiException.class,()->data(item.id()));}
        try(var files=Files.list(operations.resolve("hold-control-files"))){for(Path path:files.toList())Files.setLastModifiedTime(path,java.nio.file.attribute.FileTime.from(Instant.now().minus(Duration.ofDays(2))));}assertTrue(app.getBean(PrivacyHoldRecovery.class).cleanup(100)>0);try(var files=Files.list(operations.resolve("hold-control-files"))){assertEquals(0,files.count());}
    }
    @Test void encryptedControlEvidenceAndBlobsRotateAndRecoverAnOldArchiveBeforeOldKeysAreRetired()throws Exception {
        UUID owner=user("Synthetic rekey owner"),document=file(owner);var profile=hold(owner,"profile",owner);var fileHold=hold(owner,"files",document);Path before=archive("before-key-rotation");String metadata=sql.queryForObject("SELECT (to_jsonb(privacy_legal_holds)-'reason_ciphertext')::text FROM privacy_legal_holds WHERE id=?",String.class,profile.id());
        app.close();app=null;nextKeys(true);start();var rotated=app.getBean(PrivacyEvidenceRotation.class).runOnce(100,()->false);assertEquals(0,rotated.failed());assertEquals(5,rotated.rotated());assertEquals(metadata,sql.queryForObject("SELECT (to_jsonb(privacy_legal_holds)-'reason_ciphertext')::text FROM privacy_legal_holds WHERE id=?",String.class,profile.id()));
        restore(before);ready();assertTrue(sql.queryForObject("SELECT reason_ciphertext FROM privacy_legal_holds WHERE id=?",String.class,profile.id()).startsWith("pvc1.e2."));assertArrayEquals(BYTES,data(fileHold.id()).data());
        try(var files=Files.list(operations.resolve("hold-control-files"))){for(Path path:files.toList())Files.setLastModifiedTime(path,java.nio.file.attribute.FileTime.from(Instant.now().minus(Duration.ofDays(2))));}app.getBean(PrivacyHoldRecovery.class).cleanup(100);app.close();app=null;nextKeys(false);start();ready();assertArrayEquals(BYTES,data(fileHold.id()).data());assertEquals(1,sql.queryForObject("SELECT revision FROM privacy_legal_holds WHERE id=?",Integer.class,profile.id()));
    }
    @Test void aConflictingLiveFileIsPreservedAndCannotBeOverwrittenByAutomaticRecovery()throws Exception {
        UUID owner=user("Synthetic conflicting file owner");Path before=archive("before-conflicting-file");UUID document=file(owner);hold(owner,"files",document);byte[] conflict={9,8,7,6};Files.write(storage.resolve(document.toString()),conflict);app.close();app=null;database.resetSchema();database.restoreDatabaseArchive(before);assertThrows(Exception.class,this::start);assertNull(app);assertArrayEquals(conflict,Files.readAllBytes(storage.resolve(document.toString())));assertEquals(0,new JdbcTemplate(database.dataSource()).queryForObject("SELECT count(*) FROM privacy_legal_holds",Integer.class));
    }
    @Test void actualAdministrativeHttpDecisionsPublishOneControlAndIdempotentRetriesPublishNone()throws Exception {
        UUID owner=user("Synthetic HTTP control owner"),document=file(owner);var client=java.net.http.HttpClient.newHttpClient();String base="http://127.0.0.1:"+app.getWebServer().getPort();var json=app.getBean(ObjectMapper.class);String email=sql.queryForObject("SELECT email FROM users WHERE id=?",String.class,administrator.id());
        var login=client.send(java.net.http.HttpRequest.newBuilder(java.net.URI.create(base+"/api/v1/auth/login")).header("Origin",AuthTestSettings.ORIGIN).header("Content-Type","application/json").POST(java.net.http.HttpRequest.BodyPublishers.ofString(json.writeValueAsString(Map.of("email",email,"password",PASSWORD)))).build(),java.net.http.HttpResponse.BodyHandlers.ofString());assertEquals(200,login.statusCode());var cookies=new LinkedHashMap<String,String>();for(String header:login.headers().allValues("set-cookie")){var pair=header.split(";",2)[0].split("=",2);cookies.put(pair[0],pair[1]);}String cookie=String.join("; ",cookies.entrySet().stream().map(e->e.getKey()+"="+e.getValue()).toList());
        var body=new PrivacyHoldDto.Create(PASSWORD,owner,"files",document,"regular_exercise_of_rights","Synthetic actual HTTP preservation decision","Synthetic HTTP case",Instant.now().plusSeconds(3600),Instant.now().plusSeconds(86400));String key=UUID.randomUUID().toString();var request=java.net.http.HttpRequest.newBuilder(java.net.URI.create(base+"/api/v1/admin/privacy/holds")).header("Origin",AuthTestSettings.ORIGIN).header("Content-Type","application/json").header("Cookie",cookie).header("x-csrf-token",cookies.get("uc_csrf")).header("idempotency-key",key).POST(java.net.http.HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build();
        var created=client.send(request,java.net.http.HttpResponse.BodyHandlers.ofString());assertEquals(201,created.statusCode());long first=app.getBean(PrivacyHoldControlTransactions.class).marker().sequence();assertEquals(1,first);var retry=client.send(request,java.net.http.HttpResponse.BodyHandlers.ofString());assertEquals(201,retry.statusCode());assertEquals(created.body(),retry.body());assertEquals(first,app.getBean(PrivacyHoldControlTransactions.class).marker().sequence());var current=app.getBean(PrivacyHoldControlJournal.class).current().orElseThrow();assertEquals(1,current.state().path("files").size());assertEquals(document.toString(),current.state().path("files").get(0).path("id").asText());ready();
    }
    @Test void aPostBackupLocationHoldIsAppliedBeforeCleanupAndItsLaterReleaseDoesNotFreezeTheRestoredRoute()throws Exception {
        UUID owner=user("Synthetic route hold owner"),university=sql.queryForObject("INSERT INTO universities(slug,name,city,state_code) VALUES(?,'Synthetic campus','Synthetic city','GO') RETURNING id",UUID.class,"synthetic-"+UUID.randomUUID());var routes=new ArrayList<UUID>();for(int n=0;n<2;n++)routes.add(sql.queryForObject("INSERT INTO ride_routes(university_id,driver_id,region,meeting,distance_m,origin_address,destination_address,origin_lat,origin_lng,destination_lat,destination_lng) VALUES(?,?,'Synthetic region','Synthetic meeting',12000,'Synthetic private origin','Synthetic private destination',-16.1,-48.1,-16.2,-48.2) RETURNING id",UUID.class,university,owner));Path before=archive("before-location-hold");var hold=hold(owner,"location",routes.getFirst());
        restore(before);ready();assertEquals("Synthetic private origin",sql.queryForObject("SELECT origin_address FROM ride_routes WHERE id=?",String.class,routes.getFirst()));assertNull(sql.queryForObject("SELECT origin_address FROM ride_routes WHERE id=?",String.class,routes.get(1)));assertTrue(new String(data(hold.id()).data(),java.nio.charset.StandardCharsets.UTF_8).contains("Synthetic private origin"));review(hold,true);app.getBean(PrivacyRetentionTransactions.class).prune(100);
        restore(before);ready();assertEquals(0,sql.queryForObject("SELECT count(*) FROM ride_routes WHERE driver_id=? AND (origin_address IS NOT NULL OR destination_address IS NOT NULL OR origin_lat IS NOT NULL OR origin_lng IS NOT NULL OR destination_lat IS NOT NULL OR destination_lng IS NOT NULL)",Integer.class,owner));assertEquals(2,sql.queryForObject("SELECT count(*) FROM ride_routes WHERE driver_id=? AND meeting='Synthetic meeting' AND distance_m=12000",Integer.class,owner));assertEquals(0,sql.queryForObject("SELECT count(*) FROM privacy_retained_records WHERE user_id=?",Integer.class,owner));
    }
    @Test void actualWebpPhotosAndPdfDocumentsUploadedAfterTheArchiveRecoverAsPrivateHeldEvidence()throws Exception {
        UUID owner=user("Synthetic supported file formats owner");var actor=new Actor(owner,"user","active",null,null,null,true,Set.of());Path before=archive("before-webp-and-pdf");var image=new java.awt.image.BufferedImage(2,2,java.awt.image.BufferedImage.TYPE_INT_RGB);var png=new java.io.ByteArrayOutputStream();assertTrue(javax.imageio.ImageIO.write(image,"png",png));var service=app.getBean(com.unicarona.file.service.FileService.class);UUID photo=service.upload(actor,"photo",png.toByteArray()).id(),document=service.upload(actor,"identity","%PDF-1.7\nSynthetic actual PDF evidence\n%%EOF".getBytes(java.nio.charset.StandardCharsets.US_ASCII)).id();byte[] photoBytes=app.getBean(PrivateFileStorage.class).get(photo.toString()),pdfBytes=app.getBean(PrivateFileStorage.class).get(document.toString());var photoHold=hold(owner,"files",photo);var pdfHold=hold(owner,"files",document);for(UUID file:List.of(photo,document))Files.delete(storage.resolve(file.toString()));
        restore(before);ready();var recoveredPhoto=data(photoHold.id());var recoveredPdf=data(pdfHold.id());assertEquals("image/webp",recoveredPhoto.contentType());assertEquals("webp",recoveredPhoto.extension());assertArrayEquals(photoBytes,recoveredPhoto.data());assertEquals("application/pdf",recoveredPdf.contentType());assertEquals("pdf",recoveredPdf.extension());assertArrayEquals(pdfBytes,recoveredPdf.data());assertNull(sql.queryForObject("SELECT photo_file_id FROM users WHERE id=?",UUID.class,owner));for(UUID file:List.of(photo,document))assertEquals("FILE_NOT_FOUND",assertThrows(com.unicarona.shared.ApiException.class,()->app.getBean(com.unicarona.file.service.FileService.class).download(actor,file)).code());
    }
}
